function simulateDay(){
if ($.ctx.message.text == ".sudokudaily") {
 print("shard count not specified")
 return
}
let shardsTotal = Number(args[0])
if (isNaN(shardsTotal)) {
 shardsTotal = 0
}
let fragments=0,miningTotalFrags=0,miningTotalShards=0,shards=0;
print("=== MINING SIMULATION ===");
for(let i=1;i<=5;i++){
const roll=random(1, 100);
let frag=roll<=50?0:roll<=80?1:roll<=93?3:roll<=98?5:0;
let shar=roll<=98?0:1;
if(roll>98)print(`Mining #${i}: Roll ${roll} → 1 shard`);
miningTotalFrags+=frag;fragments+=frag;
miningTotalShards+=shar;shards+=shar;
if(roll<=98)print(`Mining #${i}: Roll ${roll} → ${frag} fragment${frag!==1?"s":""}`);
}
print(`Mining total: ${miningTotalFrags} fragments, ${miningTotalShards} shards`);
const robRoll=random(1, 100);
const target=$randrobtarget();
print(`\n=== ROBBING ${target} (target is chosen randomly among people with shards, de-equipinators are accounted for and updated) ===`);
let robSuccess=false,range="1-40",thresh=40;
if(target==="Sudoku"){
print(`Rob roll: ${robRoll} → Rob wasted`);
}else{
if($hasdeequipnator(target)){thresh=10;range="1-10";}
if(robRoll<=thresh){
robSuccess=true;shards+=1;
print(`Rob roll: ${robRoll} → Success! 1 shard (success range: ${range})`);
}else print(`Rob roll: ${robRoll} → Failed. +0 fragments (success range: ${range})`);
}
print("\n=== MINE LAYER 2 ===")
const materials = $minelayer2()

const relicIncome = (4+Math.min(shardsTotal, 40)*0.1)*3
fragments += relicIncome
print("\n=== DAILY TOTAL ===");
print(`Relic income: +${relicIncome} fragments`);
console.log(`Mining rewards: +${miningTotalFrags} fragments, ${miningTotalShards} shards`);
console.log(`Robbery: +${robSuccess?"1 shard":"0 shards"}`);
console.log(`Fragment total: ${fragments} fragments`);
console.log(`Shard total: ${shards} shards`);
print("Mine layer 2 total:")
for (const [m, c] of Object.entries(materials)) {
   print(`+${c} ${m}`)
}

return fragments+8*shards;
}
simulateDay();

